"""AI attribution: this whole file was generated by Claude (Anthropic) in Claude Code, following
design decisions made by the author. See ATTRIBUTION.md for details.

P1 v0.4 B1-strong (plan 6.4): a stateful rule over the situation text's inputs; every setting chosen on dev.

Inputs at a decision point (all known to every system): detected sounds (the shared detector before the point, class
and peak), Whisper-small transcripts, speaker tags, whether the assistant is talking, and the history, which gives the
previous point's answer (gold, as all systems get the history). The line start is the scripted one (perfect
segmentation, plan 3.1).
State: "with" (talking with the assistant, the default) or "away". The state before a point follows the previous
point's answer (R not -> away; R respond -> with; S stop without a line -> away; otherwise with); then:
  enter away if (a) an attention sound (phone, doorbell, knock; "calling out" is not a v0.4 detector class) with peak
     >= theta lies within T s before the line starts, and the line has an answer phrase, or has at most L words and
     no to-the-assistant phrase (v0.3 B1's condition); or (b) after a doorbell or knock, footsteps or a door within
     T2 s (both >= theta; new since the previous point): the silent walk to the door;
  return to "with" (each condition on or off, chosen on dev): r1 the line has a return or to-the-assistant phrase;
     r2 the user's previous line has a call-ending phrase; r3 a door sound (>= theta) since the previous point while
     away (closing the door); r4 the line's sentence embedding (all-MiniLM-L6-v2) is closer than s (cosine) to the
     assistant's last turn before the line;
  when enter and return both hold, the precedence is chosen on dev.
Decisions: R respond iff the state is "with" and the line's speaker tag is the user. S stop iff the state is "away",
or the user (by tag) said a line that has no listening-sound or keep-going phrase; else continue.
Phrase lists: fixed (v0.3's to-the-assistant list; the common listening sounds, matched as the whole line; keep-going
and call-ending phrases)
plus, as a setting, 1-3 word phrases mined from the training lines (plan 6.4): in >= 2 training lines of the class
and in none of the opposite class: answer (vs lines to the assistant), to the assistant (vs lines to others), return
(vs lines to others), call ending (the last line before a return vs other lines to others), listening sound or keep
going (vs lines where the assistant must stop).
Grid: T {1,2,3,4,6,8} s, L {1-6,8,10}, theta {0.1..0.9}, T2 {2,4,6,8,10} s, s {off, 0.3..0.7}, precedence {enter,
return}, r1 r2 r3 on/off, mined {none, from the scripts, from the training transcripts}, tags on/off, keep_exempt
on/off: 2,488,320 settings, evaluated exactly (vectorised over settings; each point depends only on its own inputs and
the gold previous answer). Three settings were added on 2026-11-15, in B1's favour, before any of its results was
final:
  - tags off treats every line as the user's: the off-the-shelf speaker tags miss about half of the user's lines
    under 1 s on dev, and the plan's rule "a line not tagged as the user is never answered" then fails on short
    lines such as "Hello?";
  - keep_exempt: a listening sound or keep-going line never enters "away" (the plan's S rule exempts them from
    stopping, but its entry condition, taken from v0.3 where these lines did not occur, made "Okay." after a ring
    look like answering the phone);
  - mined from the training transcripts: the lists are matched against Whisper transcripts, whose spellings differ
    from the scripts (for example "Mm-hmm").
usage: python -X utf8 scripts/p1v4_b1.py dev <out_dir>
"""
import itertools
import json
import os
import sys

import numpy as np

sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
import p1v4_context as C  # noqa: E402
import p1v4_data as D  # noqa: E402
import p1v4_score as S  # noqa: E402
from step0_check_batches import norm  # noqa: E402

FIXED_ASST = ["hold on", "hang on", "one sec", "one second", "give me a second", "wait for me", "pause", "ignore that",
              "never mind", "nevermind", "anyway", "sorry about that", "where was I", "where were we",
              "as I was saying", "go on", "keep going", "continue"]
FIXED_KEEP = ["keep going", "go on", "go ahead", "continue", "carry on", "ignore that", "never mind that",
              "don't stop", "keep talking"]
FIXED_END = ["bye", "goodbye", "talk later", "talk to you later", "call you back", "gotta go", "got to go",
             "see you", "speak soon", "thanks bye"]
BACKCHANNELS = {norm(x) for x in json.load(open("results/step0_v04/lines_v04.json",
                                                 encoding="utf-8"))["backchannel_common"]}
ATTN = ("phone", "doorbell", "knock")
GRID = {"T": [1, 2, 3, 4, 6, 8], "L": [1, 2, 3, 4, 5, 6, 8, 10], "theta": [round(0.1 * i, 1) for i in range(1, 10)],
        "T2": [2, 4, 6, 8, 10], "s": [None, 0.3, 0.4, 0.5, 0.6, 0.7], "prec": ["enter", "return"],
        "r1": [0, 1], "r2": [0, 1], "r3": [0, 1], "mined": ["none", "script", "transcript"], "tags": [1, 0],
        "keep_exempt": [0, 1]}
MINILM = ("sentence-transformers/all-MiniLM-L6-v2", "1110a243fdf4706b3f48f1d95db1a4f5529b4d41")


def ngrams(text, n_max=3):
    w = norm(text).split()
    return {" ".join(w[i:i + n]) for n in range(1, n_max + 1) for i in range(len(w) - n + 1)}


def mine(min_lines=2, source="script"):
    """Phrase lists mined from the training lines (all draws; distinct texts): their scripted text, or (source =
    "transcript", in B1's favour, since its lists are matched against Whisper transcripts) the Whisper-small
    transcripts of the same lines."""
    cls = {k: set() for k in ("answer", "asst", "other", "ret", "end", "away_not_end", "keep", "stop")}
    ctx = C.Context("train") if source == "transcript" else None
    for r in D.load_rows("train"):
        src = {s["id"]: s for s in r["sources"]}
        pts = sorted(r["points"], key=lambda p: p["t"])
        for i, p in enumerate(pts):
            if not p.get("line"):
                continue
            g = p["gold"]
            if ctx is None:
                text = src[p["line"]]["text"]
            else:
                key = ctx.segs.get(ctx.pid(r, p["k"]), {}).get(p["line"])
                text = ctx.text[key] if key else ""
            if g.get("R") == "respond":
                cls["asst"].add(text)
            if g.get("R") == "not":
                cls["other"].add(text)
                if p.get("category") in ("pickup", "r_react", "s_react"):
                    cls["answer"].add(text)
            if p.get("category") == "return":
                cls["ret"].add(text)
            if g.get("S") == "continue":
                cls["keep"].add(text)
            if g.get("S") == "stop":
                cls["stop"].add(text)
            if r["part"] == "episode" and g.get("R") == "not":
                nxt = next((q for q in pts[i + 1:] if q.get("line")), None)
                (cls["end"] if nxt is not None and nxt.get("category") == "return" else cls["away_not_end"]).add(text)

    def mined(pos, neg):
        count = {}
        for x in pos:
            for gram in ngrams(x):
                count[gram] = count.get(gram, 0) + 1
        banned = set().union(*[ngrams(x) for x in neg]) if neg else set()
        return sorted(gr for gr, c in count.items() if c >= min_lines and gr not in banned)
    return {"answer": mined(cls["answer"], cls["asst"]), "asst": mined(cls["asst"], cls["other"]),
            "ret": mined(cls["ret"], cls["other"]), "end": mined(cls["end"], cls["away_not_end"]),
            "keep": mined(cls["keep"], cls["stop"]), "n_lines": {k: len(v) for k, v in cls.items()}}


def has(text, phrases):
    t = f" {norm(text)} "
    return any(f" {norm(p)} " in t for p in phrases)


def sentence_embeddings(texts, batch=256):
    import torch
    import torch.nn.functional as F
    from transformers import AutoModel, AutoTokenizer
    dev = os.environ.get("P1V4_DEVICE", "cuda")
    tok = AutoTokenizer.from_pretrained(MINILM[0], revision=MINILM[1])
    m = AutoModel.from_pretrained(MINILM[0], revision=MINILM[1]).to(dev).eval()
    out = []
    with torch.no_grad():
        for i in range(0, len(texts), batch):
            enc = tok(texts[i:i + batch], padding=True, truncation=True, max_length=128,
                      return_tensors="pt").to(dev)
            h = m(**enc).last_hidden_state
            mask = enc["attention_mask"].unsqueeze(-1).float()
            e = (h * mask).sum(1) / mask.sum(1).clamp(min=1)
            out.append(F.normalize(e, dim=-1).cpu().numpy())
    return np.concatenate(out).astype(np.float32)


def prev_state_away(prev_gold):
    if prev_gold is None:
        return False
    if prev_gold.get("R") is not None:
        return prev_gold["R"] == "not"
    return prev_gold.get("S") == "stop"


def point_inputs(rows, ctx, lists):
    """Per decision point, everything the rule reads (independent of the settings). Phrase hits are indexed by the
    "mined" setting: 0 fixed lists only, 1 plus phrases mined from the scripts, 2 plus phrases mined from the
    training transcripts."""
    sets = [{k: set(v) for k, v in lists[src].items() if k != "n_lines"} for src in ("script", "transcript")]

    def hit3(text, grams, fixed, name):
        f = has(text, fixed) if fixed else False
        return [f, f or bool(grams & sets[0][name]), f or bool(grams & sets[1][name])]
    pts, line_texts, asst_texts = [], [], []
    for r in rows:
        src = {s["id"]: s for s in r["sources"]}
        order = sorted(r["points"], key=lambda p: p["t"])
        prev = {p["k"]: (order[i - 1] if i else None) for i, p in enumerate(order)}
        for p in r["points"]:
            t = p["t"]
            tr, _, tags, snd = ctx.point(r, p["k"])
            pp = prev[p["k"]]
            t_prev = pp["t"] if pp is not None else -1.0
            line = p.get("line")
            ls = src[line]["start"] if line else t
            text = tr.get(line, "") if line else ""
            hits = {}
            grams = ngrams(text)
            for name, fixed in (("answer", []), ("asst", FIXED_ASST), ("ret", FIXED_ASST), ("keep", FIXED_KEEP)):
                hits[name] = hit3(text, grams, fixed, name)
            bc = norm(text) in BACKCHANNELS                # the whole line is a listening sound (closed common set)
            hits["keep"] = [x or bc for x in hits["keep"]]
            before = [s for s in r["sources"] if s["kind"] == "speech" and s["id"] != line
                      and s["end"] <= ls + 1e-6 and s["id"] in tr]
            for name, cand in (("end_tag", [s for s in before if tags.get(s["id"]) == "user"]), ("end_any", before)):
                prev_text = tr[max(cand, key=lambda s: s["end"])["id"]] if cand else ""
                hits[name] = hit3(prev_text, ngrams(prev_text), FIXED_END, "end")
            ev = []
            for T in GRID["T"]:
                pk = [s[3] for s in snd if s[0] in ATTN and s[1] <= ls and s[2] >= ls - T]
                ev.append(max(pk) if pk else 0.0)
            go = []
            for T2 in GRID["T2"]:
                pk = [min(a[3], b[3]) for a in snd if a[0] in ("doorbell", "knock")
                      for b in snd if b[0] in ("footsteps", "door") and a[1] <= b[1] <= a[2] + T2
                      and t_prev < b[1] < t]
                go.append(max(pk) if pk else 0.0)
            dn = [s[3] for s in snd if s[0] == "door" and t_prev < s[1] < t]
            turns = [a for a in r["assistant"] if a["start"] < ls]
            pts.append({"key": (r["unit"], r["version"], p["k"]), "line": bool(line),
                        "user": bool(line) and tags.get(line) == "user", "words": len(norm(text).split()),
                        "hits": hits, "ev": ev, "go": go, "door_new": max(dn) if dn else 0.0,
                        "away_prev": prev_state_away(pp["gold"] if pp is not None else None),
                        "talking": bool(p.get("assistant_speaking")) or p["kind"] in ("S", "RS"),
                        "gold": p["gold"], "i_line": len(line_texts),
                        "i_asst": len(asst_texts) if turns else -1})
            line_texts.append(text)
            if turns:
                asst_texts.append(turns[-1]["text"])
    le = sentence_embeddings(line_texts) if line_texts else np.zeros((0, 384), np.float32)
    ae = sentence_embeddings(asst_texts) if asst_texts else np.zeros((0, 384), np.float32)
    for x in pts:
        x["sim"] = float(le[x["i_line"]] @ ae[x["i_asst"]]) if x["line"] and x["i_asst"] >= 0 else -1.0
    return pts


class Grid:
    def __init__(self, idx=None):
        names = list(GRID)
        if idx is None:
            idx = np.array(list(itertools.product(*[range(len(GRID[n])) for n in names])), dtype=np.int16)
        self.names, self.idx = names, idx
        self.col = {n: idx[:, i] for i, n in enumerate(names)}
        self.n = len(idx)
        self.theta = np.array(GRID["theta"], np.float32)[self.col["theta"]]
        self.L = np.array(GRID["L"])[self.col["L"]]
        s_vals = np.array([9.0 if v is None else v for v in GRID["s"]], np.float32)
        self.s = s_vals[self.col["s"]]
        self.prec_enter = self.col["prec"] == 0
        self.r1, self.r2, self.r3 = (self.col[k] == 1 for k in ("r1", "r2", "r3"))
        self.mined = self.col["mined"]
        self.tags_off = self.col["tags"] == 1                  # GRID["tags"] = [1, 0]: index 1 = tags not used
        self.keep_exempt = self.col["keep_exempt"] == 1

    def setting(self, i):
        return {n: GRID[n][int(self.idx[i, j])] for j, n in enumerate(self.names)}

    def decide(self, x):
        """Vectorised over settings: (S stop?, R respond?) for point x."""
        h = {k: np.array(v, bool)[self.mined] for k, v in x["hits"].items()}
        h["end"] = np.where(self.tags_off, h["end_any"], h["end_tag"])
        ev_ok = np.array(x["ev"], np.float32)[self.col["T"]] >= self.theta
        go_ok = np.array(x["go"], np.float32)[self.col["T2"]] >= self.theta
        short = x["words"] <= self.L
        # the line counts as the user's by its speaker tag, or always when the setting does not use tags
        line_user = (x["user"] | self.tags_off) if x["line"] else np.zeros(self.n, bool)
        answer_like = h["answer"] | (short & ~h["asst"])
        answer_like &= ~(self.keep_exempt & h["keep"])        # keep_exempt: listening sounds and "go on" never enter
        enter = go_ok | (line_user & ev_ok & answer_like)
        ret = np.zeros(self.n, bool)
        if x["line"]:
            ret |= line_user & self.r1 & (h["ret"] | h["asst"])
            ret |= line_user & (x["sim"] > self.s)
            ret |= self.r2 & h["end"]
        if x["away_prev"]:
            ret |= self.r3 & (x["door_new"] >= self.theta)
        both = enter & ret
        away = np.where(both, self.prec_enter, np.where(enter, True, np.where(ret, False, x["away_prev"])))
        stop = away | (line_user & ~h["keep"])
        respond = ~away & line_user
        return stop, respond


def evaluate(rows, pts, grid):
    """Five-part mean and floors for every setting (exact, as p1v4_score.unit_table counts them)."""
    ex = S.excluded_units()
    by_key = {x["key"]: x for x in pts}
    unit_ok = {}
    meta = {}
    floor_n, floor_ok = {}, {}
    for r in rows:
        if r["unit"] in ex:
            continue
        meta[r["unit"]] = (r["part"], r["subset"], r["spec"].get("which") if r["part"] == "floor" else None)
        ok_u = unit_ok.setdefault(r["unit"], np.ones(grid.n, bool))
        for p in r["points"]:
            x = by_key[(r["unit"], r["version"], p["k"])]
            stop, respond = grid.decide(x)
            g = p["gold"]
            ok = np.ones(grid.n, bool)
            if g.get("S") is not None:
                ok &= stop if g["S"] == "stop" else ~stop
            if g.get("R") is not None:
                ok &= respond if g["R"] == "respond" else ~respond
            ok_u &= ok
            if r["part"] == "floor":
                kind = meta[r["unit"]][2].split("_")[0]
                floor_n[kind] = floor_n.get(kind, 0) + 1
                floor_ok[kind] = floor_ok.get(kind, 0) + ok.astype(np.int32)
    part_sum = {p: np.zeros(grid.n, np.int32) for p in S.PARTS}
    part_n = dict.fromkeys(S.PARTS, 0)
    for u, ok in unit_ok.items():
        part, subset, _ = meta[u]
        if part in part_sum and subset is None:
            part_sum[part] += ok
            part_n[part] += 1
    parts = {p: part_sum[p] / max(1, part_n[p]) for p in S.PARTS if part_n[p]}
    primary = np.mean([parts[p] for p in parts], 0)
    floors = {k: floor_ok[k] / floor_n[k] for k in floor_n}
    return primary, parts, floors


def choose(primary, floors):
    low = np.min(np.stack(list(floors.values())), 0)
    ok = low >= S.FLOOR_MIN
    if ok.any():
        val = np.where(ok, primary, -1.0)
        met = True
    else:
        val = np.where(low >= low.max() - 1e-12, primary, -1.0)
        met = False
    return int(np.argmax(val)), met, low


def decisions_for(pts, grid, i):
    one = Grid(grid.idx[i:i + 1])
    out = {}
    for x in pts:
        stop, respond = one.decide(x)
        d = {}
        if x["talking"]:
            d["S"] = "stop" if stop[0] else "continue"
        if x["line"]:
            d["R"] = "respond" if respond[0] else "not"
        out[x["key"]] = d
    return out


def main(which, out_dir, quiet=False):
    """quiet (final run on test or replication, freeze amendment 4.2 item 6): write the files, print no metric."""
    os.makedirs(out_dir, exist_ok=True)
    lists_path = os.path.join(out_dir, "mined_phrases.json")
    if not os.path.exists(lists_path):
        json.dump({"script": mine(source="script"), "transcript": mine(source="transcript")},
                  open(lists_path, "w"), indent=1)
    lists = json.load(open(lists_path))
    for src in ("script", "transcript"):
        print(f"mined phrases ({src}):", {k: len(v) for k, v in lists[src].items() if k != "n_lines"},
              lists[src]["n_lines"], flush=True)
    rows = D.load_rows(which)
    ctx = C.Context(which)
    pts = point_inputs(rows, ctx, lists)
    grid = Grid()
    print(f"{len(pts)} points, {grid.n} settings", flush=True)
    primary, parts, floors = evaluate(rows, pts, grid)
    i, met, low = choose(primary, floors)
    best = grid.setting(i)
    tie = (low >= low[i] - 1e-12) & (primary >= primary[i] - 1e-12) if not met else \
        (low >= S.FLOOR_MIN) & (primary >= primary[i] - 1e-12)
    res = {"setting": best, "floors_met": met, "primary": float(primary[i]),
           "parts": {p: float(a[i]) for p, a in parts.items()}, "floors": {k: float(a[i]) for k, a in floors.items()},
           "lowest_floor": float(low[i]), "n_settings": grid.n,
           "n_settings_meeting_floors": int((low >= S.FLOOR_MIN).sum()),
           "n_settings_tied_with_chosen": int(tie.sum()), "best_lowest_floor": float(low.max()),
           "best_primary_any_floor": float(primary.max())}
    json.dump(res, open(os.path.join(out_dir, f"b1_{which}.json"), "w"), indent=1)
    dec = decisions_for(pts, grid, i)
    json.dump({"|".join(map(str, k)): v for k, v in dec.items()}, open(os.path.join(out_dir,
                                                                                    f"decisions_{which}.json"), "w"))
    if quiet:
        print(f"b1 on {which}: setting chosen and decisions written to {out_dir} (metrics not printed)")
    else:
        print(json.dumps(res, indent=1))


if __name__ == "__main__":
    main(*sys.argv[1:3])
